import{_ as a,o,c as t,ag as r}from"./chunks/framework.DO6ntPSX.js";const p=JSON.parse('{"title":"查询拆解","description":"","frontmatter":{},"headers":[],"relativePath":"zh/features/query-decomposition.md","filePath":"zh/features/query-decomposition.md","lastUpdated":1785115728000}'),i={name:"zh/features/query-decomposition.md"};function l(n,e,s,d,c,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="查询拆解" tabindex="-1">查询拆解 <a class="header-anchor" href="#查询拆解" aria-label="Permalink to &quot;查询拆解&quot;">​</a></h1><p>复杂问题被拆分为子查询并发检索，然后结果融合为单一综合回答。</p><h2 id="为什么要拆解" tabindex="-1">为什么要拆解？ <a class="header-anchor" href="#为什么要拆解" aria-label="Permalink to &quot;为什么要拆解？&quot;">​</a></h2><p>像&quot;比较 2023 年和 2024 年报告关于可再生能源的发现&quot;这样的问题需要：</p><ol><li>找到 2023 年报告的发现</li><li>找到 2024 年报告的发现</li><li>比较两者</li></ol><p>单次检索查询很可能会遗漏其中一份报告或稀释相关性信号。拆解确保每个子问题获得自己专注的检索。</p><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><ol><li><strong>分析</strong>：LLM 分析原始问题并将其拆分为原子子查询</li><li><strong>并发检索</strong>：每个子查询通过 <code>ThreadPoolExecutor</code> 并行分派到检索流程</li><li><strong>结果融合</strong>：所有子查询的结果按 chunk 去重并评分</li><li><strong>上下文组装</strong>：构建单一组合上下文发送给 LLM 生成最终回答</li></ol><h2 id="性能" tabindex="-1">性能 <a class="header-anchor" href="#性能" aria-label="Permalink to &quot;性能&quot;">​</a></h2><ul><li>子查询并发运行，因此总延迟接近最慢的单个查询，而非总和</li><li>Chunk 去重防止同一文档被重复计算</li><li>动态 Top-K 应用于融合结果集</li></ul><h2 id="集成" tabindex="-1">集成 <a class="header-anchor" href="#集成" aria-label="Permalink to &quot;集成&quot;">​</a></h2><p>查询拆解自动用于：</p><ul><li><strong>Standard RAG</strong> 流程（<code>answer_query</code>）</li><li><strong>Graph RAG</strong> 流程（<code>graph_rag_pipeline</code>）</li></ul><p>没有单独的用户开关；Mneme 根据查询结构判断是否需要拆解。</p>',14)])])}const _=a(i,[["render",l]]);export{p as __pageData,_ as default};
